<?php
if (session_status() === PHP_SESSION_NONE) session_start();
require_once __DIR__ . '/portal.php';
$roles = ['Rural Health Midwife' => ['MIDWIFE', 'MidwifeDashboard.php'], 'Public Health Nurse' => ['NURSE', 'NurseDashboard.php'], 'Medical Technologist' => ['MEDTECH', 'MedTechDashboard.php'], 'Sanitary Inspector' => ['SANITARY_INSPECTOR', 'SanitaryDashboard.php'], 'Administrative Staff' => ['ADMIN_STAFF', 'AdminStaffDashboard.php']];
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $role = $_POST['role'] ?? ''; $email = trim($_POST['email'] ?? ''); $password = $_POST['password'] ?? '';
    if (!isset($roles[$role]) || !$email || !$password) $error = 'Enter your role, email address, and password.';
    elseif (empty($pdo)) $error = 'The database is unavailable. Please try again later.';
    else try {
        [$staffType, $route] = $roles[$role];
        $statement = $pdo->prepare('SELECT u.id AS user_id, u.email, u.password_hash, u.first_name, u.last_name, s.id AS staff_id, s.staff_type FROM users u INNER JOIN staff s ON s.user_id = u.id WHERE u.email = :email AND u.is_active = 1 AND s.is_active = 1 AND s.staff_type = :staff_type LIMIT 1');
        $statement->execute(['email' => $email, 'staff_type' => $staffType]); $staff = $statement->fetch();
        if (!$staff || !password_verify($password, $staff['password_hash'])) $error = 'Invalid staff credentials or selected role.';
        else { $_SESSION['rhu_staff_login'] = ['id' => (int)$staff['user_id'], 'staff_id' => (int)$staff['staff_id'], 'email' => $staff['email'], 'role' => $role, 'staff_type' => $staff['staff_type'], 'name' => trim($staff['first_name'] . ' ' . $staff['last_name'])]; portalAudit($pdo, (int)$staff['user_id'], 'RHU staff login', 'staff', (int)$staff['staff_id']); header('Location: ' . $route); exit; }
    } catch (PDOException $exception) { error_log('RHU staff login: ' . $exception->getMessage()); $error = 'Unable to sign in right now. Please try again later.'; }
}
?>
